fn unit_rank(c: Str) -> Int {
  if c == "d" {
    return 0
  }
  if c == "h" {
    return 1
  }
  if c == "m" {
    return 2
  }
  if c == "s" {
    return 3
  }
  return -1
}

fn unit_secs(rank: Int) -> Int {
  if rank == 0 {
    return 86400
  }
  if rank == 1 {
    return 3600
  }
  if rank == 2 {
    return 60
  }
  return 1
}

pub fn duration(s: Str) -> Result[Int, Str] {
  var total = 0
  var num = ""
  var prev = -1
  for c in s.chars() {
    if "0123456789".contains(c) {
      num = num + c
    } else {
      let r = unit_rank(c)
      if num == "" or r < 0 or r <= prev {
        return Err("invalid duration")
      }
      total = total + num.to_int().unwrap_or(0) * unit_secs(r)
      num = ""
      prev = r
    }
  }
  if num != "" or prev < 0 {
    return Err("invalid duration")
  }
  return Ok(total)
}
